#!/bin/bash
# Brings up a live DAOS server+agent cluster and creates a pool+container --
# the *live cluster* half of the workflow, exclusive across tickets (see
# README.md's Isolation model). Requires per-host config files under
# ./files/ (daos_server-<host>.yml, daos_control-<host>.yml,
# daos_agent-<host>.yml) -- these are hardware/topology-specific, not
# generated by generate-daos-env.sh; get them via
# `new-ticket-worktree.sh --skeleton-from <a-ticket-with-a-working-files-dir>`
# or by hand.
#
# Usage:
#   start-daos.sh [--no-pool] [-h|--help]
#
#   --no-pool   bring up the servers and agents only: no pool, no container
#               (e.g. when the pool creation itself is what is being tested,
#               as in a run-<topic>-fi.sh reproduction script)
#
# After `dmg storage format`, waits (60 s at most) until every engine of the
# ./files/daos_server-*.yml configs is "joined" in `dmg system query`, then
# prints the verbose system query; on timeout it warns and continues. With a
# pool, prints POOL_UUID=... and CONT_UUID=... at the end.

# set -x
set -u -e -o pipefail

CWD="$(realpath "$(dirname "$0")")"

usage() {
	sed -n '2,/^$/p' "$0" | sed 's/^# \{0,1\}//'
}

NO_POOL=false
for arg in "$@" ; do
	case "$arg" in
		--no-pool) NO_POOL=true ;;
		-h|--help) usage ; exit 0 ;;
		*) echo ">>> [ERROR] unknown argument: $arg" >&2 ; usage >&2 ; exit 1 ;;
	esac
done

bash "$CWD/cleanup.sh"

source "$CWD/env.sh"

# Expected engine count: one "storage:" block per engine in each host's config
# (the same heuristic as the format-ready wait below).
ENGINE_NB=0
for host in $(nodeset -e $SERVER_NODES) ; do
	ENGINE_NB=$((ENGINE_NB + $(grep -c -E -e "^[[:space:]]+storage:$" "$CWD/files/daos_server-$host.yml")))
done

echo
echo ">>> Seting-up Development environment"
{
	cat <<- EOF
	# set -x
	set -e -o pipefail

	pushd "$DAOS_SRC" &> /dev/null
	source utils/sl/setup_local.sh "$DAOS_SRC/utils/sl/build_vars-Linux.sh"
	popd > /dev/null
	set -u

	sudo -E "$DAOS_SRC/utils/setup_daos_server_helper.sh"
	chmod -x "$DAOS_INSTALL/bin/daos_server_helper"
	EOF
} | ssh $(nodeset -e -I 0 $SERVER_NODES) bash -s

echo
echo ">>> Installing DAOS server configuration file"
{
	cat <<- EOF
	# set -x
	set -u -e -o pipefail

	mkdir -pv /var/daos/daos-monitor/bin
	chmod -v 777 /var/daos
	EOF
} | clush -BLS -l root -w $ALL_NODES bash -s
{
	cat <<- EOF
	# set -x
	set -u -e -o pipefail

	rm -frv /usr/lib/systemd/system/daos_server.service.d/override.conf
	EOF
} | clush -BLS -l root -w $SERVER_NODES bash -s
for host in $(nodeset -e $SERVER_NODES) ; do
	scp "$CWD/files/daos_server-$host.yml" root@$host:"/etc/daos/daos_server.yml"
done
clush -BLS -l root -w $SERVER_NODES systemctl daemon-reload

echo
echo ">>> Installing DAOS control configuration file"
scp "$CWD/files/daos_control-$ADMIN_NODE.yml" "root@$ADMIN_NODE:/etc/daos/daos_control.yml"

echo
echo ">>> Installing DAOS agent configuration file"
{
	cat <<- EOF
	# set -x
	set -u -e -o pipefail

	rm -frv /usr/lib/systemd/system/daos_agent.service.d/override.conf
	EOF
} | clush -BLS -l root -w $CLIENT_NODES bash -s
for host in $(nodeset -e $CLIENT_NODES) ; do
	scp "$CWD/files/daos_agent-$host.yml" "root@$host:/etc/daos/daos_agent.yml"
done
clush -BLS -l root -w $CLIENT_NODES systemctl daemon-reload

echo
echo ">>> Starting DAOS server"
clush -BLS -w $SERVER_NODES -l root systemctl start daos_server
timeout=10
echo -n -e ">>> Waiting DAOS servers to be started: timeout=$timeout \r"
while [[ $timeout -gt 0 ]] && ! clush -BLS -w $SERVER_NODES systemctl is-active daos_server > /dev/null 2>&1 ; do
	echo -n -e ">>> Waiting DAOS servers to be started: timeout=$timeout \r"
	sleep 1
	timeout=$((timeout-1))
done
if [[ $timeout -eq 0 ]] ; then
	echo ">>> [ERROR] DAOS servers could not be started                      "
	exit 1
fi
echo ">>> DAOS servers are running                                      "

timeout=60
while [[ $timeout -gt 0 ]] ; do
	{
		cat <<- EOF
		# set -x
		set -u -e -o pipefail

		engine_ready_nb=\$(grep -c -e "format required" /var/daos/daos_server.log 2> /dev/null)
		engine_nb=\$(grep -c -E -e "^[[:space:]]+storage:$" "/etc/daos/daos_server.yml")
		[[ \$engine_ready_nb -eq \$engine_nb ]]
		EOF
	} | clush -BLS -w $SERVER_NODES bash -s > /dev/null 2>&1 && break
	# } | clush -BLS -w $SERVER_NODES bash -s > /dev/null && break
	echo -n -e ">>> Waiting DAOS file system for being ready to be formatted : timeout=$timeout \r"
	sleep 1
	timeout=$((timeout-1))
done
if [[ $timeout -eq 0 ]] ; then
	echo ">>> [ERROR] File system can not be formatted                                     "
	exit 1
fi
echo ">>> DAOS file system ready to be formatted                                       "

{
	cat <<- EOF
	# set -x
	set -e -o pipefail

	pushd "$DAOS_SRC" > /dev/null
	source utils/sl/setup_local.sh &> /dev/null
	popd > /dev/null
	set -u

	echo
	echo ">>> Formatting DAOS file system"
	$DMG_BIN $DMG_OPTS storage format --verbose --force

	echo
	timeout=60
	while [[ \$timeout -gt 0 ]] ; do
		if $DMG_BIN $DMG_OPTS system query --json 2> /dev/null | jq -e '.response.members | length == $ENGINE_NB and all(.state == "joined")' > /dev/null ; then
			break
		fi
		echo -n -e ">>> Waiting DAOS engines to be joined ($ENGINE_NB expected): timeout=\$timeout \r"
		sleep 1
		timeout=\$((timeout - 1))
	done
	if [[ \$timeout -gt 0 ]] ; then
		echo ">>> DAOS engines are joined                                                        "
	else
		echo ">>> [WARN] not all the $ENGINE_NB DAOS engines joined within 60 s -- continuing anyway" >&2
	fi

	echo
	echo ">>> Querying DAOS system"
	$DMG_BIN $DMG_OPTS system query --verbose
	EOF
} | ssh root@$ADMIN_NODE bash -s

if $NO_POOL ; then
	echo
	echo ">>> --no-pool: skipping pool and container creation"
else
	set +e
	{
		cat <<- EOF
		# set -x
		set -e -o pipefail

		pushd "$DAOS_SRC" > /dev/null
		source utils/sl/setup_local.sh &> /dev/null
		popd > /dev/null
		set -u

		echo
		echo ">>> Checking storage usage"
		$DMG_BIN $DMG_OPTS storage query usage

		echo
		echo ">>> Creating DAOS pool $POOL_NAME"
		$DMG_BIN $DMG_OPTS pool create $POOL_OPTS $POOL_NAME

		echo
		echo ">>> Disable Aggregation"
		$DMG_BIN $DMG_OPTS pool set-prop $POOL_NAME reclaim:disabled

		echo
		echo ">>> Query pool"
		$DMG_BIN $DMG_OPTS pool query $POOL_NAME

		echo
		echo ">>> Check pool aggregation policy"
		$DMG_BIN $DMG_OPTS pool get-prop $POOL_NAME reclaim

		echo
		echo ">>> Query space"
		$DMG_BIN $DMG_OPTS storage query usage
		true
		EOF
	} | ssh root@$ADMIN_NODE bash -s
	set -e

	echo
	echo ">>> Search pool UUID"
	POOL_UUID=$({
		cat <<- EOF
		# set -x
		set -e -o pipefail

		pushd "$DAOS_SRC" > /dev/null
		source utils/sl/setup_local.sh &> /dev/null
		popd > /dev/null
		set -u

		$DMG_BIN pool query -o /etc/daos/daos_control.yml --json $POOL_NAME | jq -r '.response.uuid'
		EOF
	} | ssh root@$ADMIN_NODE bash -s)
	echo "POOL_UUID=$POOL_UUID"
fi

echo
echo ">>> Starting DAOS agents"
clush -BLS -w $CLIENT_NODES -l root systemctl start daos_agent
timeout=10
echo -n -e ">>> Waiting DAOS agents to be started: timeout=$timeout  \r"
while [[ $timeout -gt 0 ]] && ! clush -BLS -w $CLIENT_NODES systemctl is-active daos_agent > /dev/null 2>&1 ; do
	echo -n -e ">>> Waiting DAOS agents to be started: timeout=$timeout  \r"
	sleep 1
	timeout=$((timeout-1))
done
if [[ $timeout -eq 0 ]] ; then
	echo ">>> [ERROR] DAOS agents could not be started                      "
	exit 2
fi
echo ">>> DAOS agents are running                                      "

echo
timeout=10
while [[ $timeout -gt 0 ]] ; do
	echo -n -e ">>> Waiting DAOS agent to be ready: timeout=$timeout \r"
	sleep 1
	set +e
	((--timeout))
	set -e
done
echo ">>> DAOS agent is ready                                                                         "

if $NO_POOL ; then
	echo
	echo ">>> DAOS cluster is up (no pool): $ENGINE_NB engine(s) on $SERVER_NODES, agent(s) on $CLIENT_NODES"
	exit 0
fi

{
	cat <<- EOF
	# set -x
	set -e -o pipefail

	pushd "$DAOS_SRC" > /dev/null
	source utils/sl/setup_local.sh &> /dev/null
	popd > /dev/null
	set -u

	echo
	echo ">>> Creating DAOS container: name=$CONT_NAME"
	$DAOS_BIN container create $CONT_OPTS $POOL_NAME $CONT_NAME
	echo
	echo ">>> Query container: name=$CONT_NAME"
	$DAOS_BIN container query $POOL_NAME $CONT_NAME
	EOF
} | ssh $LOGIN_NODE bash -s

echo ">>> Searching container UUID"
CONT_UUID=$({
	cat <<- EOF
	set -e -o pipefail

	pushd "$DAOS_SRC" > /dev/null
	source utils/sl/setup_local.sh &> /dev/null
	popd > /dev/null
	set -u

	$DAOS_BIN container query --json $POOL_NAME $CONT_NAME | jq -r '.response.container_uuid'
	EOF
} | ssh $LOGIN_NODE bash -s)
echo "CONT_UUID=${CONT_UUID}"
